async function main() {
  const category = await prisma.category.upsert({
    where: { slug: "dsa" },
    update: { name: "Data Structures & Algorithms" },
    create: {
      group: "Technology", name: "Data Structures & Algorithms", slug: "dsa" },
  });

  const subcategories = [
    { name: "Linked Lists, Hashing & Heaps", slug: "linked-lists-hashing-heaps" },
    { name: "Dynamic Programming & Greedy", slug: "dynamic-programming-greedy" },
    { name: "Arrays, Strings & Dynamic Programming", slug: "arrays-strings-dynamic-programming" },
    { name: "DSA Fundamentals & Problem Solving", slug: "dsa-fundamentals-problem-solving" },
    { name: "Stacks & Queues", slug: "stacks-queues" },
    { name: "Trees & Binary Search Trees", slug: "trees-binary-search-trees" },
    { name: "Graphs & Graph Algorithms", slug: "graphs-graph-algorithms" },
  ];

  const subcategoryMap = new Map<string, string>();
  for (const sub of subcategories) {
    const record = await prisma.subcategory.upsert({
      where: { categoryId_slug: { categoryId: category.id, slug: sub.slug } },
      update: { name: sub.name },
      create: { name: sub.name, slug: sub.slug, categoryId: category.id },
    });
    subcategoryMap.set(sub.slug, record.id);
  }

  for (const item of interviewQuestions) {
    const subcategoryId = subcategoryMap.get(item.subcategorySlug);
    if (!subcategoryId) throw new Error(`Missing subcategory: ${item.subcategorySlug}`);
    await prisma.interviewQuestion.upsert({
      where: { slug: item.slug },
      update: {
        question: item.question, categoryId: category.id, subcategoryId,
        experienceLevel: item.experienceLevel, difficulty: item.difficulty,
        interviewType: item.interviewType, shortDescription: item.shortDescription,
        explanation: item.explanation, sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer, keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes, followUpQuestions: item.followUpQuestions,
        tags: item.tags, isPublished: true,
      },
      create: {
        question: item.question, slug: item.slug, categoryId: category.id, subcategoryId,
        experienceLevel: item.experienceLevel, difficulty: item.difficulty,
        interviewType: item.interviewType, shortDescription: item.shortDescription,
        explanation: item.explanation, sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer, keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes, followUpQuestions: item.followUpQuestions,
        tags: item.tags, isPublished: true,
      },
    });
  }

  console.log(`DSA interview seed completed: ${interviewQuestions.length} questions.`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
}).finally(async () => {
  await prisma.$disconnect();
});